import {accuracyDonut,comparisonBars,xpLine} from './stats-charts.js?v=visual-activities-20261008';
import {xpSummary,dailyRanking,pokerLevels} from './xp.js';
import {t} from './i18n.js?v=visual-activities-20261008';
import {results,percent,savedResults,pendingCount,autoSave} from './progress.js?v=visual-activities-20261008';
import {practiceModules} from './practice-modules.js?v=visual-activities-20261008';
let filter='all';
const score=rows=>percent(rows.filter(x=>x.correct).length,rows.length);
export function statsDashboard(){const all=results(),rows=filter==='week'?all.filter(x=>x.at>=Date.now()-7*86400000):all;const xp=xpSummary(all),ranking=dailyRanking(all);const correct=rows.filter(x=>x.correct).length,latest=new Map(rows.map(x=>[x.module+'/'+x.question,x])),total=practiceModules.reduce((n,m)=>n+m.quiz.length,0);const half=Math.floor(rows.length/2),before=rows.slice(0,half),after=rows.slice(half);const topics=['rules','staff','formats','terms','math','decisions'].map(theme=>({theme,rows:rows.filter(x=>x.theme===theme),total:practiceModules.filter(x=>x.theme===theme).reduce((n,m)=>n+m.quiz.length,0)}));const tested=topics.filter(x=>x.rows.length),strong=[...tested].sort((a,b)=>score(b.rows)-score(a.rows)),weak=[...tested].sort((a,b)=>score(a.rows)-score(b.rows));
return `<div class="stats-dashboard"><div class="page-heading"><div><span class="eyebrow">STATS · POKERINNO</span><h1>${t('stats.evolution')}</h1><p>${t('stats.intro')}</p></div></div><div class="stats-filters"><button data-stats-filter="all" aria-pressed="${filter==='all'}">${t('stats.all')}</button><button data-stats-filter="week" aria-pressed="${filter==='week'}">${t('stats.week')}</button></div><div class="stats-metrics">${[[t('stats.correct'),correct],[t('stats.errors'),rows.length-correct],[t('stats.accuracy'),score(rows)+'%'],[t('stats.done'),latest.size+' / '+total]].map(([label,value])=>`<article><span>${label}</span>${label===t('stats.accuracy')?accuracyDonut(correct,rows.length):`<strong>${value}</strong>`}</article>`).join('')}</div>${xpPanel(xp,ranking)}<section class="stats-panel"><h2>${t('stats.comparison')}</h2><p>${t('stats.compareNote')}</p><div class="stats-duel">${[[t('stats.villain'),before],[t('stats.hero'),after]].map(([label,part])=>`<article><h3>${label}</h3><strong>${rows.length>=2?score(part)+'%':'—'}</strong><p>${part.length} ${t('practice.activities')}</p></article>`).join('')}</div>${rows.length>=2?comparisonBars(score(before),score(after)):''}<p class="stats-delta">${rows.length>=2?(score(after)-score(before)>0?'+':'')+(score(after)-score(before))+' '+t('stats.points'):t('stats.needData')}</p></section><section class="stats-panel"><h2>${t('stats.themes')}</h2>${topics.map(({theme,rows:items,total:themeTotal})=>`<details class="stats-topic"><summary><span>${t('practice.'+theme)}<small class="theme-total">${new Set(items.map(x=>x.module+'/'+x.question)).size} / ${themeTotal} ${t('practice.activities')}</small></span><strong>${items.length?score(items)+'%':'—'}</strong><span class="stats-bar"><i style="width:${score(items)}%"></i></span></summary><p>${items.filter(x=>x.correct).length} ${t('stats.correct')} · ${items.filter(x=>!x.correct).length} ${t('stats.errors')}</p>${practiceModules.filter(x=>x.theme===theme).map(m=>{const attempts=items.filter(x=>x.module===m.key);return `<a class="stats-module" href="#practice-module/${m.key}"><span>${m.t?.pt||m.title}<small class="theme-total">${new Set(attempts.map(x=>x.question)).size} / ${m.quiz.length} ${t('practice.activities')}</small></span><strong>${attempts.length?score(attempts)+'%':'—'}</strong></a>`}).join('')}</details>`).join('')}</section><section class="stats-panel"><h2>SWOT</h2><div class="stats-swot">${[['strength',strong[0]?.theme],['weakness',weak[0]?.theme],['opportunity',topics.find(x=>!x.rows.length)?.theme],['threat',null]].map(([key,theme])=>`<article><h3>${t('stats.'+key)}</h3><p>${theme?t('practice.'+theme):t(key==='threat'?'stats.threatText':'stats.needData')}</p></article>`).join('')}</div></section><section class="stats-panel"><h2>${t('stats.study')}</h2><p>${t('stats.studyNote')}</p>${(weak.length?weak.slice(0,2):topics.slice(0,2)).map(({theme})=>`<a class="stats-module" href="#practice-module/${practiceModules.find(m=>m.theme===theme).key}">${t('practice.'+theme)} <span>↗</span></a>`).join('')}</section><section class="stats-panel"><h2>${t('stats.history')}</h2>${rows.length?rows.slice(-12).reverse().map(r=>`<div class="stats-history"><span>${t('practice.'+r.theme)}<small>${new Date(r.at).toLocaleString(document.documentElement.lang||'pt-BR')}</small></span><strong>${t(r.correct?'quiz.correct':'quiz.incorrect')}</strong></div>`).join(''):`<p>${t('stats.empty')}</p>`}</section>${trainingHistory()}<p class="stats-storage">${t('training.storage')}</p></div>`}
function xpPanel(xp,ranking){const todayDate=new Date();const today=[todayDate.getFullYear(),String(todayDate.getMonth()+1).padStart(2,'0'),String(todayDate.getDate()).padStart(2,'0')].join('-');const todayXP=ranking.find(x=>x.day===today)?.xp||0;const bestPrevious=Math.max(0,...ranking.filter(x=>x.day!==today).map(x=>x.xp));return `<section class="stats-panel xp-panel"><div class="xp-heading"><div><span class="eyebrow">${t('xp.lifetime')}</span><h2>${t('xp.level.'+xp.level.key)}</h2></div><strong>${xp.total} XP</strong></div><div class="level-meter" role="progressbar" aria-label="${t('xp.nextLevel')}" aria-valuenow="${xp.progress}" aria-valuemin="0" aria-valuemax="100"><i style="width:${xp.progress}%"></i></div><p>${xp.next?`${xp.next.min-xp.total} XP · ${t('xp.nextLevel')}: ${t('xp.level.'+xp.next.key)}`:t('xp.maxLevel')}</p><details class="xp-rules"><summary>${t('xp.graduation')}</summary><div class="level-list">${pokerLevels.map(level=>`<div class="${xp.total>=level.min?'level-unlocked':''}"><span>${t('xp.level.'+level.key)}</span><strong>${level.min} XP</strong></div>`).join('')}</div><p>${t('xp.rules')}</p></details><h3>${t('xp.dailyTrend')}</h3>${xpLine(ranking)}<h3>${t('xp.personalRanking')}</h3><p>${t('xp.challenge')}: ${todayXP} / ${bestPrevious||'—'} XP</p>${ranking.length?`<ol class="xp-ranking">${ranking.slice(0,5).map((day,i)=>`<li><span>${i+1}</span><time>${new Date(day.day+'T12:00:00').toLocaleDateString(document.documentElement.lang||'pt-BR')}</time><strong>${day.xp} XP</strong></li>`).join('')}</ol>`:`<p>${t('xp.empty')}</p>`}</section>`}
function trainingHistory(){const grouped=new Map();for(const row of savedResults()){const key=row.session||'legacy-'+row.module+'-'+new Date(row.at).toLocaleDateString();if(!grouped.has(key))grouped.set(key,[]);grouped.get(key).push(row)}const sessions=[...grouped.values()].sort((a,b)=>b.at(-1).at-a.at(-1).at);return `<section class="stats-panel training-history"><h2>${t('training.history')}</h2>${(!autoSave()||pendingCount())?`<button class="save-activities" data-save-activities>${t('training.saveNow')}</button><p>${pendingCount()} ${t('training.pending')}</p>`:''}${sessions.length?sessions.slice(0,20).map(rows=>{const module=practiceModules.find(m=>m.key===rows[0].module);return `<details class="training-session"><summary><span>${module?.t?.pt||module?.title||t('practice.'+rows[0].theme)}<small>${new Date(rows[0].at).toLocaleString(document.documentElement.lang||'pt-BR')}</small></span><strong>${score(rows)}%</strong></summary><div class="training-session-metrics"><span>${rows.length} ${t('stats.done')}</span><span>${rows.filter(x=>x.correct).length} ${t('stats.correct')}</span><span>${rows.filter(x=>!x.correct).length} ${t('stats.errors')}</span><span>${xpSummary(rows).total} XP</span></div><a class="stats-module" href="#practice-module/${rows[0].module}">${t('training.repeat')}</a></details>`}).join(''):`<p>${t('training.empty')}</p>`}<p>${t('training.historyNote')}</p></section>`}
window.addEventListener('academy:activities-saved',()=>{if(document.querySelector('.stats-dashboard'))document.querySelector('#app').innerHTML=statsDashboard()});
document.addEventListener('click',event=>{const button=event.target.closest('[data-stats-filter]');if(!button)return;filter=button.dataset.statsFilter;document.querySelector('#app').innerHTML=statsDashboard()});
